func TestEarlyHintsRequest(t *testing.T) { run(t, testEarlyHintsRequest) }
func testEarlyHintsRequest(t *testing.T, mode testMode) {
	var wg sync.WaitGroup
	wg.Add(1)
	cst := newClientServerTest(t, mode, HandlerFunc(func(w ResponseWriter, r *Request) {
		h := w.Header()

		h.Add("Content-Length", "123") // must be ignored
		h.Add("Link", "</style.css>; rel=preload; as=style")
		h.Add("Link", "</script.js>; rel=preload; as=script")
		w.WriteHeader(StatusEarlyHints)

		wg.Wait()

		h.Add("Link", "</foo.js>; rel=preload; as=script")
		w.WriteHeader(StatusEarlyHints)

		w.Write([]byte("Hello"))
	}))

	checkLinkHeaders := func(t *testing.T, expected, got []string) {
		t.Helper()

		if len(expected) != len(got) {
			t.Errorf("got %d expected %d", len(got), len(expected))
		}

		for i := range expected {
			if expected[i] != got[i] {
				t.Errorf("got %q expected %q", got[i], expected[i])
			}
		}
	}

	checkExcludedHeaders := func(t *testing.T, header textproto.MIMEHeader) {
		t.Helper()

		for _, h := range []string{"Content-Length", "Transfer-Encoding"} {
			if v, ok := header[h]; ok {
				t.Errorf("%s is %q; must not be sent", h, v)
			}
		}
	}

	var respCounter uint8
	trace := &httptrace.ClientTrace{
		Got1xxResponse: func(code int, header textproto.MIMEHeader) error {
			switch respCounter {
			case 0:
				checkLinkHeaders(t, []string{"</style.css>; rel=preload; as=style", "</script.js>; rel=preload; as=script"}, header["Link"])
				checkExcludedHeaders(t, header)

				wg.Done()
			case 1:
				checkLinkHeaders(t, []string{"</style.css>; rel=preload; as=style", "</script.js>; rel=preload; as=script", "</foo.js>; rel=preload; as=script"}, header["Link"])
				checkExcludedHeaders(t, header)

			default:
				t.Error("Unexpected 1xx response")
			}

			respCounter++

			return nil
		},
	}
	req, _ := NewRequestWithContext(httptrace.WithClientTrace(context.Background(), trace), "GET", cst.ts.URL, nil)

	res, err := cst.c.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer res.Body.Close()

	checkLinkHeaders(t, []string{"</style.css>; rel=preload; as=style", "</script.js>; rel=preload; as=script", "</foo.js>; rel=preload; as=script"}, res.Header["Link"])
	if cl := res.Header.Get("Content-Length"); cl != "123" {
		t.Errorf("Content-Length is %q; want 123", cl)
	}

	body, _ := io.ReadAll(res.Body)
	if string(body) != "Hello" {
		t.Errorf("Read body %q; want Hello", body)
	}
}

// TestClientServerTLSConnWrapper verifies that the Transport and Server can
// negotiate an HTTP/2 connection using a net.Conn that has a
// "ConnectionState() tls.ConnectionState" method but is not a *tls.Conn.
func TestClientServerTLSConnWrapper(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		protocols := &Protocols{}
		protocols.SetHTTP1(true)
		protocols.SetHTTP2(true)

		li := fakeNetListen()
		server := &Server{
			Handler: HandlerFunc(func(w ResponseWriter, r *Request) {
				if r.TLS == nil {
					t.Fatal("server request has no TLS ConnectionState")
				}
			}),
			Protocols: protocols,
		}
		defer server.Close()
		go server.Serve(&testListener{
			accept: func() (net.Conn, error) {
				conn, err := li.Accept()
				if err != nil {
					return nil, err
				}
				return &testTLSConn{
					Conn: conn,
					state: tls.ConnectionState{
						Version:            tls.VersionTLS13,
						CipherSuite:        tls.TLS_AES_128_GCM_SHA256,
						NegotiatedProtocol: "h2",
					},
				}, nil
			},
			close: li.Close,
			addr:  li.Addr(),
		})

		tr := &Transport{
			DialTLS: func(network, address string) (net.Conn, error) {
				return &testTLSConn{
					Conn: li.connect(),
					state: tls.ConnectionState{
						Version:            tls.VersionTLS13,
						CipherSuite:        tls.TLS_AES_128_GCM_SHA256,
						NegotiatedProtocol: "h2",
					},
				}, nil
			},
			Protocols: protocols,
		}

		req, _ := NewRequest("GET", "https://example.tld", nil)
		resp, err := tr.RoundTrip(req)
		if err != nil {
			t.Fatal(err)
		}
		resp.Body.Close()
		if resp.StatusCode != 200 {
			t.Errorf("response status %v, want 200", resp.StatusCode)
		}
		if resp.TLS == nil {
			t.Fatal("server request has no TLS ConnectionState")
		}
	})
}

type testListener struct {
	accept func() (net.Conn, error)
	close  func() error
	addr   net.Addr
}

func (li *testListener) Accept() (net.Conn, error) { return li.accept() }
func (li *testListener) Close() error              { return li.close() }
func (li *testListener) Addr() net.Addr            { return li.addr }

type testTLSConn struct {
	net.Conn
	state tls.ConnectionState
}

func (c *testTLSConn) Handshake() error                     { return nil }
func (c *testTLSConn) ConnectionState() tls.ConnectionState { return c.state }
