func TestStripPrefix(t *testing.T) { run(t, testStripPrefix) }
func testStripPrefix(t *testing.T, mode testMode) {
	h := HandlerFunc(func(w ResponseWriter, r *Request) {
		w.Header().Set("X-Path", r.URL.Path)
		w.Header().Set("X-RawPath", r.URL.RawPath)
	})
	ts := newClientServerTest(t, mode, StripPrefix("/foo/bar", h)).ts

	c := ts.Client()

	cases := []struct {
		reqPath string
		path    string // If empty we want a 404.
		rawPath string
	}{
		{"/foo/bar/qux", "/qux", ""},
		{"/foo/bar%2Fqux", "/qux", "%2Fqux"},
		{"/foo%2Fbar/qux", "", ""}, // Escaped prefix does not match.
		{"/bar", "", ""},           // No prefix match.
	}
	for _, tc := range cases {
		t.Run(tc.reqPath, func(t *testing.T) {
			res, err := c.Get(ts.URL + tc.reqPath)
			if err != nil {
				t.Fatal(err)
			}
			res.Body.Close()
			if tc.path == "" {
				if res.StatusCode != StatusNotFound {
					t.Errorf("got %q, want 404 Not Found", res.Status)
				}
				return
			}
			if res.StatusCode != StatusOK {
				t.Fatalf("got %q, want 200 OK", res.Status)
			}
			if g, w := res.Header.Get("X-Path"), tc.path; g != w {
				t.Errorf("got Path %q, want %q", g, w)
			}
			if g, w := res.Header.Get("X-RawPath"), tc.rawPath; g != w {
				t.Errorf("got RawPath %q, want %q", g, w)
			}
		})
	}
}

// https://golang.org/issue/18952.
func TestStripPrefixNotModifyRequest(t *testing.T) {
	h := StripPrefix("/foo", NotFoundHandler())
	req := httptest.NewRequest("GET", "/foo/bar", nil)
	h.ServeHTTP(httptest.NewRecorder(), req)
	if req.URL.Path != "/foo/bar" {
		t.Errorf("StripPrefix should not modify the provided Request, but it did")
	}
}

func TestRequestLimit(t *testing.T) { run(t, testRequestLimit, http3SkippedMode) }
func testRequestLimit(t *testing.T, mode testMode) {
	bytesPerHeader := len("header12345: val12345\r\n")
	numHeaders := ((DefaultMaxHeaderBytes + 4096) / bytesPerHeader) + 1

	cst := newClientServerTest(t, mode, HandlerFunc(func(w ResponseWriter, r *Request) {
		t.Fatalf("didn't expect to get request in Handler")
	}), func(s *Server) {
		s.MaxHeaderValueCount = numHeaders
	}, optQuietLog)
	req, _ := NewRequest("GET", cst.ts.URL, nil)
	for i := range numHeaders {
		req.Header.Set(fmt.Sprintf("header%05d", i), fmt.Sprintf("val%05d", i))
	}
	res, err := cst.c.Do(req)
	if res != nil {
		defer res.Body.Close()
	}
	if mode == http2Mode {
		// In HTTP/2, the result depends on a race. If the client has received the
		// server's SETTINGS before RoundTrip starts sending the request, then RoundTrip
		// will fail with an error. Otherwise, the client should receive a 431 from the
		// server.
		if err == nil && res.StatusCode != 431 {
			t.Fatalf("expected 431 response status; got: %d %s", res.StatusCode, res.Status)
		}
	} else {
		// In HTTP/1, we expect a 431 from the server.
		// Some HTTP clients may fail on this undefined behavior (server replying and
		// closing the connection while the request is still being written), but
		// we do support it (at least currently), so we expect a response below.
		if err != nil {
			t.Fatalf("Do: %v", err)
		}
		if res.StatusCode != 431 {
			t.Fatalf("expected 431 response status; got: %d %s", res.StatusCode, res.Status)
		}
	}
}

func TestRequestHeaderValueCountLimit(t *testing.T) {
	run(t, testRequestHeaderValueCountLimit, http3SkippedMode)
}
func testRequestHeaderValueCountLimit(t *testing.T, mode testMode) {
	tests := []struct {
		name       string
		limit      int
		setup      func(req *Request)
		wantStatus int
	}{
		{
			name:  "below limit",
			limit: 15,
			setup: func(req *Request) {
				// Send considerably below the limit, to account for the client
				// automatically adding pseudo-headers and headers that it can
				// infer.
				for i := range 5 {
					req.Header.Add(fmt.Sprintf("X-Header-%d", i), "val")
				}
			},
			wantStatus: 200,
		},
		{
			name:  "above limit",
			limit: 15,
			setup: func(req *Request) {
				for i := range 16 {
					req.Header.Add(fmt.Sprintf("X-Header-%d", i), "val")
				}
			},
			wantStatus: 431,
		},
		{
			name:  "comma separated values count as one",
			limit: 15,
			setup: func(req *Request) {
				vals := make([]string, 16)
				for i := range vals {
					vals[i] = "val"
				}
				req.Header.Add("X-Comma", strings.Join(vals, ", "))
			},
			wantStatus: 200,
		},
		{
			name:  "multiple values count as multiple",
			limit: 15,
			setup: func(req *Request) {
				for range 16 {
					req.Header.Add("X-Repeated", "val")
				}
			},
			wantStatus: 431,
		},
		{
			// Comma separated Trailer values are counted as multiple, because
			// each value becomes its own field / a key in Request.Trailer.
			// This is different from TestRequestTrailerHeaderValueCountLimit
			// which tests the actual sending of the trailer, this just tests
			// the Trailer header declaration.
			name:  "comma separated trailer values count as multiple",
			limit: 15,
			setup: func(req *Request) {
				req.Body = NoBody
				req.TransferEncoding = []string{"chunked"}
				req.Trailer = make(Header)
				for i := range 16 {
					req.Trailer[fmt.Sprintf("X-Trailer-%d", i)] = nil
				}
			},
			wantStatus: 431,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cst := newClientServerTest(t, mode, HandlerFunc(func(w ResponseWriter, r *Request) {
				w.WriteHeader(StatusOK)
			}), func(s *Server) {
				s.MaxHeaderValueCount = tt.limit
			}, optQuietLog)

			req, _ := NewRequest("GET", cst.ts.URL, nil)
			tt.setup(req)

			res, err := cst.c.Do(req)
			if err != nil {
				t.Fatal(err)
			}
			defer res.Body.Close()
			if res.StatusCode != tt.wantStatus {
				t.Errorf("got status %d, want %d", res.StatusCode, tt.wantStatus)
			}
		})
	}
}

func TestRequestTrailerHeaderValueCountLimit(t *testing.T) {
	run(t, testRequestTrailerHeaderValueCountLimit, http3SkippedMode)
}
func testRequestTrailerHeaderValueCountLimit(t *testing.T, mode testMode) {
	tests := []struct {
		name    string
		limit   int
		setup   func(req *Request)
		wantErr bool
	}{
		{
			name:  "below limit",
			limit: 15,
			setup: func(req *Request) {
				req.Trailer = make(Header)
				for i := range 14 {
					req.Trailer.Add(fmt.Sprintf("X-Trailer-%d", i), "val")
				}
			},
		},
		{
			name:  "above limit",
			limit: 15,
			setup: func(req *Request) {
				req.Trailer = make(Header)
				for i := range 16 {
					req.Trailer.Add(fmt.Sprintf("X-Trailer-%d", i), "val")
				}
			},
			wantErr: true,
		},
		{
			name:  "comma separated values count as one",
			limit: 15,
			setup: func(req *Request) {
				req.Trailer = make(Header)
				vals := make([]string, 16)
				for i := range vals {
					vals[i] = "val"
				}
				req.Trailer.Add("X-Comma-Trailer", strings.Join(vals, ", "))
			},
		},
		{
			name:  "multiple values count as multiple",
			limit: 15,
			setup: func(req *Request) {
				req.Trailer = make(Header)
				for range 16 {
					req.Trailer.Add("X-Repeated-Trailer", "val")
				}
			},
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cst := newClientServerTest(t, mode, HandlerFunc(func(w ResponseWriter, r *Request) {
				_, err := io.Copy(io.Discard, r.Body)
				if (err != nil) != tt.wantErr {
					t.Errorf("Read = %v, want %v", err, tt.wantErr)
				}
			}), func(s *Server) {
				s.MaxHeaderValueCount = tt.limit
			}, optQuietLog)

			req, _ := NewRequest("GET", cst.ts.URL, strings.NewReader("some body"))
			req.TransferEncoding = []string{"chunked"}
			tt.setup(req)

			// Do will return an error in HTTP/2 due to RST_STREAM, but will
			// succeed in HTTP/1.
			res, err := cst.c.Do(req)
			if err != nil && !tt.wantErr {
				t.Fatalf("unexpected Do error: %v", err)
			}
			if err == nil {
				res.Body.Close()
			}
		})
	}
}

type neverEnding byte

func (b neverEnding) Read(p []byte) (n int, err error) {
	for i := range p {
		p[i] = byte(b)
	}
	return len(p), nil
}

type bodyLimitReader struct {
	mu     sync.Mutex
	count  int
	limit  int
	closed chan struct{}
}

func (r *bodyLimitReader) Read(p []byte) (int, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	select {
	case <-r.closed:
		return 0, errors.New("closed")
	default:
	}
	if r.count > r.limit {
		return 0, errors.New("at limit")
	}
	r.count += len(p)
	for i := range p {
		p[i] = 'a'
	}
	return len(p), nil
}

func (r *bodyLimitReader) Close() error {
	r.mu.Lock()
	defer r.mu.Unlock()
	close(r.closed)
	return nil
}

func TestRequestBodyLimit(t *testing.T) { run(t, testRequestBodyLimit) }
func testRequestBodyLimit(t *testing.T, mode testMode) {
	const limit = 1 << 20
	cst := newClientServerTest(t, mode, HandlerFunc(func(w ResponseWriter, r *Request) {
		r.Body = MaxBytesReader(w, r.Body, limit)
		n, err := io.Copy(io.Discard, r.Body)
		if err == nil {
			t.Errorf("expected error from io.Copy")
		}
		if n != limit {
			t.Errorf("io.Copy = %d, want %d", n, limit)
		}
		mbErr, ok := err.(*MaxBytesError)
		if !ok {
			t.Errorf("expected MaxBytesError, got %T", err)
		}
		if mbErr.Limit != limit {
			t.Errorf("MaxBytesError.Limit = %d, want %d", mbErr.Limit, limit)
		}
	}))

	body := &bodyLimitReader{
		closed: make(chan struct{}),
		limit:  limit * 200,
	}
	req, _ := NewRequest("POST", cst.ts.URL, body)

	// Send the POST, but don't care it succeeds or not. The
	// remote side is going to reply and then close the TCP
	// connection, and HTTP doesn't really define if that's
	// allowed or not. Some HTTP clients will get the response
	// and some (like ours, currently) will complain that the
	// request write failed, without reading the response.
	//
	// But that's okay, since what we're really testing is that
	// the remote side hung up on us before we wrote too much.
	resp, err := cst.c.Do(req)
	if err == nil {
		resp.Body.Close()
	}
	// Wait for the Transport to finish writing the request body.
	// It will close the body when done.
	<-body.closed

	if body.count > limit*100 {
		t.Errorf("handler restricted the request body to %d bytes, but client managed to write %d",
			limit, body.count)
	}
}

// TestClientWriteShutdown tests that if the client shuts down the write
// side of their TCP connection, the server doesn't send a 400 Bad Request.
func TestClientWriteShutdown(t *testing.T) { run(t, testClientWriteShutdown, http3SkippedMode) }
func testClientWriteShutdown(t *testing.T, mode testMode) {
	if runtime.GOOS == "plan9" {
		t.Skip("skipping test; see https://golang.org/issue/17906")
	}
	ts := newClientServerTest(t, mode, HandlerFunc(func(w ResponseWriter, r *Request) {})).ts
	conn, err := net.Dial("tcp", ts.Listener.Addr().String())
	if err != nil {
		t.Fatalf("Dial: %v", err)
	}
	err = conn.(*net.TCPConn).CloseWrite()
	if err != nil {
		t.Fatalf("CloseWrite: %v", err)
	}

	bs, err := io.ReadAll(conn)
	if err != nil {
		t.Errorf("ReadAll: %v", err)
	}
	got := string(bs)
	if got != "" {
		t.Errorf("read %q from server; want nothing", got)
	}
}

// Tests that chunked server responses that write 1 byte at a time are
// buffered before chunk headers are added, not after chunk headers.
func TestServerBufferedChunking(t *testing.T) {
	conn := new(testConn)
	conn.readBuf.Write([]byte("GET / HTTP/1.1\r\nHost: foo\r\n\r\n"))
	conn.closec = make(chan bool, 1)
	ls := &oneConnListener{conn}
	go Serve(ls, HandlerFunc(func(rw ResponseWriter, req *Request) {
		rw.(Flusher).Flush() // force the Header to be sent, in chunking mode, not counting the length
		rw.Write([]byte{'x'})
		rw.Write([]byte{'y'})
		rw.Write([]byte{'z'})
	}))
	<-conn.closec
	if !bytes.HasSuffix(conn.writeBuf.Bytes(), []byte("\r\n\r\n3\r\nxyz\r\n0\r\n\r\n")) {
		t.Errorf("response didn't end with a single 3 byte 'xyz' chunk; got:\n%q",
			conn.writeBuf.Bytes())
	}
}

// Tests that the server flushes its response headers out when it's
// ignoring the response body and waits a bit before forcefully
// closing the TCP connection, causing the client to get a RST.
// See https://golang.org/issue/3595
func TestServerGracefulClose(t *testing.T) {
	// Not parallel: modifies the global rstAvoidanceDelay.
	run(t, testServerGracefulClose, []testMode{http1Mode}, testNotParallel)
}
func testServerGracefulClose(t *testing.T, mode testMode) {
	runTimeSensitiveTest(t, []time.Duration{
		1 * time.Millisecond,
		5 * time.Millisecond,
		10 * time.Millisecond,
		50 * time.Millisecond,
		100 * time.Millisecond,
		500 * time.Millisecond,
		time.Second,
		5 * time.Second,
	}, func(t *testing.T, timeout time.Duration) error {
		SetRSTAvoidanceDelay(t, timeout)
		t.Logf("set RST avoidance delay to %v", timeout)

		const bodySize = 5 << 20
		req := []byte(fmt.Sprintf("POST / HTTP/1.1\r\nHost: foo.com\r\nContent-Length: %d\r\n\r\n", bodySize))
		for i := 0; i < bodySize; i++ {
			req = append(req, 'x')
		}

		cst := newClientServerTest(t, mode, HandlerFunc(func(w ResponseWriter, r *Request) {
			Error(w, "bye", StatusUnauthorized)
		}))
		// We need to close cst explicitly here so that in-flight server
		// requests don't race with the call to SetRSTAvoidanceDelay for a retry.
		defer cst.close()
		ts := cst.ts

		conn, err := net.Dial("tcp", ts.Listener.Addr().String())
		if err != nil {
			return err
		}
		writeErr := make(chan error)
		go func() {
			_, err := conn.Write(req)
			writeErr <- err
		}()
		defer func() {
			conn.Close()
			// Wait for write to finish. This is a broken pipe on both
			// Darwin and Linux, but checking this isn't the point of
			// the test.
			<-writeErr
		}()

		br := bufio.NewReader(conn)
		lineNum := 0
		for {
			line, err := br.ReadString('\n')
			if err == io.EOF {
				break
			}
			if err != nil {
				return fmt.Errorf("ReadLine: %v", err)
			}
			lineNum++
			if lineNum == 1 && !strings.Contains(line, "401 Unauthorized") {
				t.Errorf("Response line = %q; want a 401", line)
			}
		}
		return nil
	})
}

